// Helper function to get flower translation
export const getFlowerTranslation = (lang, flowerId) => {
  const translations = FLOWER_TRANSLATIONS[lang] || FLOWER_TRANSLATIONS['en'];
  return translations[flowerId] || FLOWER_TRANSLATIONS['en'][flowerId];
};

// Helper to check if translation exists
export const hasFlowerTranslation = (lang, flowerId) => {
  return FLOWER_TRANSLATIONS[lang] && FLOWER_TRANSLATIONS[lang][flowerId];
};